export const GQA_SCORES = "// GQA / MQA, dispatch 1 of 2: probs = softmax(mask(scale * Q @ K_g^T)).\n//\n// Layout:\n//   q:      [B, H,       L, D]  f32, row-major\n//   k:      [B, kv_heads, S, D] f32, row-major   <- fewer heads than q\n//   mask:   [MB, MH, MR, S]     f32, row-major — the additive attention bias\n//   probs:  [B, H,       L, S]  f32, row-major\n//\n// Structurally this is ops/attention's scores kernel. The only difference is\n// which head of K a query head reads, and that difference is two lines, which is\n// the point: sharing KV heads is an addressing change, not an arithmetic one.\n// Everything about masking, the scale and the softmax is unchanged, and is\n// documented in ops/attention rather than restated here.\n//\n// The dispatch is exactly [L, H, B] — over the *query* heads, since every query\n// head still gets its own probability row. As in attention, every invocation has\n// real work and no bounds guard is written, because a guard nothing can trip is\n// a guard no test can keep honest (rule 1). Contract: H % kv_heads == 0, checked\n// by the caller (reference.ts throws), so the integer division below is exact.\n\nstruct Params {\n  H: u32,\n  // Key / value heads. H is plain MHA, 1 is MQA, a divisor of H is GQA.\n  kv_heads: u32,\n  L: u32,\n  S: u32,\n  D: u32,\n  scale: f32,\n  causal: u32,\n  query_offset: i32,\n  // The broadcast shape of `mask`, each either 1 or the full dimension; the\n  // last axis is always S. `mask_heads` counts *query* heads, since the mask is\n  // applied after the KV head is chosen (measured against torch — see\n  // reference.ts).\n  mask_batch: u32,\n  mask_heads: u32,\n  mask_rows: u32,\n  // Issue #117. `S` stays the address stride for `k` (`k_head` below is still\n  // `kv_head * S * D`) — this only bounds the softmax scan. Defaults to `S`\n  // (append rather than insert, so this field's byte offset does not move\n  // `query_offset`'s — `llm/engine-q8-resident.ts#GQA_QUERY_OFFSET_BYTE`\n  // copies that offset, rule 2). See reference.ts's `sEff` doc for the\n  // caller's safety contract.\n  s_eff: u32,\n}\n\n@group(0) @binding(0) var<storage, read> q: array<f32>;\n@group(0) @binding(1) var<storage, read> k: array<f32>;\n@group(0) @binding(2) var<storage, read> mask: array<f32>;\n@group(0) @binding(3) var<storage, read_write> probs: array<f32>;\n@group(0) @binding(4) var<uniform> params: Params;\n\nconst WORKGROUP_SIZE: u32 = 256u;\n\n// Stands in for the -infinity PyTorch adds as `attn_bias`; WGSL cannot write an\n// infinity literal. See ops/attention/wgsl/scores.wgsl for the measurements that\n// show -FLT_MAX behaves identically for every input this op accepts.\nconst MASKED: f32 = -3.402823e+38;\n\nvar<workgroup> shared_val: array<f32, 256>;\n\n@compute @workgroup_size(256)\nfn main(\n  @builtin(workgroup_id) wg: vec3<u32>,\n  @builtin(local_invocation_id) local_id: vec3<u32>,\n) {\n  let i = wg.x;                                  // query position\n  let batch = wg.z;\n  let head = wg.y;                               // query head\n  let tid = local_id.x;\n\n  let q_head = batch * params.H + head;\n  // Contiguous groups: query heads 0..g-1 share KV head 0, g..2g-1 share KV head\n  // 1, and so on. Strided groups (`head % params.kv_heads`) are the other\n  // reading and are wrong; both agree at kv_heads == H and at kv_heads == 1, so\n  // only the middle cases can tell them apart. The batch stride is kv_heads, not\n  // H — K has fewer heads per batch, and reusing H here walks past its end.\n  let kv_head = batch * params.kv_heads + head / (params.H / params.kv_heads);\n\n  let q_row = (q_head * params.L + i) * params.D;\n  let k_head = kv_head * params.S * params.D;\n  let p_row = (q_head * params.L + i) * params.S;\n\n  // Where this query row's slice of the bias starts; each axis collapses to 0\n  // when the caller broadcast it. Identical to ops/attention — deliberately, so\n  // one mask serves both ops.\n  let mb = select(0u, batch, params.mask_batch > 1u);\n  let mh = select(0u, head, params.mask_heads > 1u);\n  let mr = select(0u, i, params.mask_rows > 1u);\n  let m_row = ((mb * params.mask_heads + mh) * params.mask_rows + mr) * params.S;\n\n  // Pass 1: scaled dot products, straight into `probs`. Bounded by `s_eff`,\n  // not `S` — positions `[s_eff, S)` are never read, not masked-then-summed\n  // (issue #117; see reference.ts's `sEff` doc).\n  var local_max: f32 = MASKED;\n  for (var j = tid; j < params.s_eff; j += WORKGROUP_SIZE) {\n    var value: f32 = MASKED;\n    if (params.causal == 0u || i32(j) <= i32(i) + params.query_offset) {\n      var dot: f32 = 0.0;\n      for (var d: u32 = 0u; d < params.D; d += 1u) {\n        dot += q[q_row + d] * k[k_head + j * params.D + d];\n      }\n      // PyTorch's float `attn_mask`, added rather than selected on. See\n      // ops/attention/wgsl/scores.wgsl.\n      value = dot * params.scale + mask[m_row + j];\n    }\n    probs[p_row + j] = value;\n    local_max = max(local_max, value);\n  }\n\n  shared_val[tid] = local_max;\n  workgroupBarrier();\n  for (var stride = WORKGROUP_SIZE / 2u; stride > 0u; stride >>= 1u) {\n    if (tid < stride) {\n      shared_val[tid] = max(shared_val[tid], shared_val[tid + stride]);\n    }\n    workgroupBarrier();\n  }\n  let row_max = shared_val[0];\n  workgroupBarrier();\n\n  // Pass 2: exponentiate in place, and sum. The row max comes off first because\n  // exp() overflows f32 at 89 and attention logits reach the hundreds.\n  var local_sum: f32 = 0.0;\n  for (var j = tid; j < params.s_eff; j += WORKGROUP_SIZE) {\n    let e = exp(probs[p_row + j] - row_max);\n    probs[p_row + j] = e;\n    local_sum += e;\n  }\n\n  shared_val[tid] = local_sum;\n  workgroupBarrier();\n  for (var stride = WORKGROUP_SIZE / 2u; stride > 0u; stride >>= 1u) {\n    if (tid < stride) {\n      shared_val[tid] += shared_val[tid + stride];\n    }\n    workgroupBarrier();\n  }\n  // Every key masked — reachable only through `mask`, and returned as zeros\n  // because 1/0 here is +inf and 0 * inf is NaN. The condition is the *sum* and\n  // not the row maximum: `local_max` starts at MASKED so the maximum cannot\n  // report -inf, while the sum is 0 exactly when no score was finite. See\n  // ops/attention/wgsl/scores.wgsl for the torch measurements.\n  let inv_sum = select(1.0 / shared_val[0], 0.0, shared_val[0] == 0.0);\n  workgroupBarrier();\n\n  // Pass 3: normalise. Masked columns are already 0 and stay 0. Columns\n  // `[s_eff, S)` are never written by any pass — whatever `probs` held there\n  // before this dispatch stays there, and `context.wgsl` must never read it\n  // (it also stops at `s_eff`, given the same params buffer — see that\n  // file's doc).\n  for (var j = tid; j < params.s_eff; j += WORKGROUP_SIZE) {\n    probs[p_row + j] = probs[p_row + j] * inv_sum;\n  }\n}\n";

/**
 * ops/gqa/wgsl/context.wgsl
 *
 * bindings: [probs f32 [B,H,L,S], v f32 [B,kvHeads,S,Dv], out f32 [B,H,L,Dv], uniform]
 * uniform:  [u32 H, u32 kvHeads, u32 L, u32 S, u32 Dv, u32 s_eff]
 *           s_eff is index 5 (byte 20) — must agree with GQA_SCORES' s_eff every step.
 * dispatch: [L, H, B]
 */
export const GQA_CONTEXT = "// GQA / MQA, dispatch 2 of 2: output = probs @ V_g.\n//\n// Layout:\n//   probs:  [B, H,        L, S]  f32, row-major — what scores.wgsl produced\n//   v:      [B, kv_heads, S, Dv] f32, row-major   <- fewer heads than probs\n//   output: [B, H,        L, Dv] f32, row-major\n//\n// ops/attention's context kernel with the same one change scores.wgsl makes:\n// which head of V a query head reads. Nothing here knows the mask exists —\n// masked columns arrive as exactly 0 from the softmax — which is why sharing KV\n// heads and choosing a causal convention stay independent of each other.\n//\n// Dispatch is exactly [L, H, B], over the query heads, so no bounds guard is\n// reachable and none is written (rule 1).\n\nstruct Params {\n  H: u32,\n  kv_heads: u32,\n  L: u32,\n  S: u32,\n  Dv: u32,\n  // Issue #117, same field and same contract as scores.wgsl's: bounds the\n  // `probs @ V` sum, `S` stays `v`'s per-head stride. Must be given the same\n  // value `scores.wgsl` was — `probs` columns past it were never written by\n  // that dispatch (see scores.wgsl's doc), so reading further here would read\n  // whatever this buffer held before. Default `S` (appended, not inserted —\n  // no existing field's offset moves).\n  s_eff: u32,\n}\n\n@group(0) @binding(0) var<storage, read> probs: array<f32>;\n@group(0) @binding(1) var<storage, read> v: array<f32>;\n@group(0) @binding(2) var<storage, read_write> output: array<f32>;\n@group(0) @binding(3) var<uniform> params: Params;\n\nconst WORKGROUP_SIZE: u32 = 256u;\n\n@compute @workgroup_size(256)\nfn main(\n  @builtin(workgroup_id) wg: vec3<u32>,\n  @builtin(local_invocation_id) local_id: vec3<u32>,\n) {\n  let i = wg.x;                                  // query position\n  let batch = wg.z;\n  let head = wg.y;                               // query head\n\n  let q_head = batch * params.H + head;\n  // Same mapping as scores.wgsl, and it has to stay the same: K and V are\n  // indexed by the same KV head, so a disagreement between the two dispatches\n  // would attend to one head's keys and read another head's values.\n  let kv_head = batch * params.kv_heads + head / (params.H / params.kv_heads);\n\n  let p_row = (q_head * params.L + i) * params.S;\n  let v_head = kv_head * params.S * params.Dv;\n  let o_row = (q_head * params.L + i) * params.Dv;\n\n  // One output channel per invocation, striding when Dv exceeds the workgroup.\n  for (var c = local_id.x; c < params.Dv; c += WORKGROUP_SIZE) {\n    var acc: f32 = 0.0;\n    for (var j: u32 = 0u; j < params.s_eff; j += 1u) {\n      acc += probs[p_row + j] * v[v_head + j * params.Dv + c];\n    }\n    output[o_row + c] = acc;\n  }\n}\n";

/**
 * ops/activation/wgsl/kernel.wgsl
 *
 * bindings: [input f32 [N], out f32 [N], uniform]
 * uniform:  [u32 N, u32 kind, f32 alpha]  (kind: ops/activation ACTIVATION — silu = 1)
 * dispatch: [ceil(N / 256)]
 */
export const ACTIVATION = "// Elementwise activations.\n//\n// Every kind here is a pure function of one element: no layout, no second\n// buffer, `N` is all the kernel is told. Snake looks like it belongs and does\n// not — its alpha is a trained per-channel tensor, so it needs a storage\n// binding and a channel stride, and it lives in `ops/snake`. See\n// `ops/snake/reference.ts` for that decision.\n//\n//   0 ReLU²      max(0, x)²                     BitNet 2B-4T FFN\n//   1 SiLU       x · sigmoid(x)                 torch.nn.SiLU\n//   2 ELU        x if x > 0 else α(eˣ - 1)      torch.nn.ELU, α default 1.0\n//   3 Tanh       tanh(x)                        torch.tanh\n//   4 GELU       0.5x(1 + erf(x/√2))            torch gelu, approximate=\"none\"\n//   5 GELU tanh  0.5x(1 + tanh(√(2/π)(x + 0.044715x³)))   approximate=\"tanh\"\n//\n// 4 and 5 are different functions, not two spellings of one: they part company\n// by 4.73e-4 at x = 2.699. torch's default is 4, so this op's default is 4.\n//\n// Layout:\n//   input:  [N] f32\n//   output: [N] f32\n\nstruct Params {\n  N: u32,\n  activation_type: u32,\n  alpha: f32,  // ELU's negative-branch scale; ignored by every other kind\n}\n\n@group(0) @binding(0) var<storage, read> input: array<f32>;\n@group(0) @binding(1) var<storage, read_write> output: array<f32>;\n@group(0) @binding(2) var<uniform> params: Params;\n\n/// erfc for u >= 0: Abramowitz & Stegun 7.1.26, whose stated error bound is\n/// 1.5e-7 — the ulp of 1 in f32, so it is as close as this type gets. WGSL has\n/// no erf and no erfc, so the exact GELU has to carry one.\nfn erfc_nonneg(u: f32) -> f32 {\n  let t = 1.0 / (1.0 + 0.3275911 * u);\n  let poly = t * (0.254829592\n      + t * (-0.284496736\n      + t * (1.421413741\n      + t * (-1.453152027\n      + t * 1.061405429))));\n  return poly * exp(-u * u);\n}\n\n@compute @workgroup_size(256)\nfn main(\n  @builtin(global_invocation_id) gid: vec3<u32>,\n) {\n  let idx = gid.x;\n  if (idx >= params.N) {\n    return;\n  }\n\n  let x = input[idx];\n  var y: f32;\n\n  switch (params.activation_type) {\n    case 0u: {\n      // ReLU²: max(0, x)²\n      let relu_x = max(0.0, x);\n      y = relu_x * relu_x;\n    }\n    case 1u: {\n      // SiLU: x * sigmoid(x)\n      y = x / (1.0 + exp(-x));\n    }\n    case 2u: {\n      // ELU. `x > 0` as torch writes it; at x = 0 both arms are 0 anyway.\n      if (x > 0.0) {\n        y = x;\n      } else {\n        y = params.alpha * (exp(x) - 1.0);\n      }\n    }\n    case 3u: {\n      y = tanh(x);\n    }\n    case 4u: {\n      // GELU, exact. Written through erfc rather than erf so neither side\n      // cancels: for x >= 0, 1 + erf(u) is 2 - erfc(u), and for x < 0 it is\n      // erfc(|u|) outright, rather than 1 + (1 - erfc) — which for x = -8 is a\n      // subtraction between two f32 numbers a hair either side of 1, and\n      // returns exactly zero where the answer is -3e-14.\n      //\n      // Stated as a contract, not as something these tests check: the naive\n      // arrangement was written in and the suite stayed green (measured). It\n      // cannot catch it, for two compounding reasons — the harness passes an\n      // element on absolute agreement below 1e-6, and every value this affects\n      // is far below that; and the f64 reference computes `1 + erf` and so\n      // cancels in the same place. Kept because it is free and right, not\n      // because a red test demanded it.\n      let u = x * 0.70710678118654752;\n      let q = erfc_nonneg(abs(u));\n      if (x >= 0.0) {\n        y = x * (1.0 - 0.5 * q);\n      } else {\n        y = 0.5 * x * q;\n      }\n    }\n    default: {\n      // GELU, tanh approximation. √(2/π) = 0.7978845608028654.\n      y = 0.5 * x * (1.0 + tanh(0.7978845608028654 * (x + 0.044715 * x * x * x)));\n    }\n  }\n\n  output[idx] = y;\n}\n";

/**
 * ops/elementwise/wgsl/kernel.wgsl
 *
 * bindings: [a f32 [N], b f32 [N], out f32 [N], uniform]
 * uniform:  [u32 N, u32 kind]  (kind: ops/elementwise ELEMENTWISE — add = 0, multiply = 1)
 * dispatch: [ceil(N / 256)]
 */
export const ELEMENTWISE = "// Elementwise operations: add, multiply\n//\n// Used for residual connections and gating.\n//\n// Layout:\n//   a:      [N] f32\n//   b:      [N] f32\n//   output: [N] f32\n\nstruct Params {\n  N: u32,\n  op: u32,  // 0 = add, 1 = multiply\n}\n\n@group(0) @binding(0) var<storage, read> a: array<f32>;\n@group(0) @binding(1) var<storage, read> b: array<f32>;\n@group(0) @binding(2) var<storage, read_write> output: array<f32>;\n@group(0) @binding(3) var<uniform> params: Params;\n\n@compute @workgroup_size(256)\nfn main(\n  @builtin(global_invocation_id) gid: vec3<u32>,\n) {\n  let idx = gid.x;\n  if (idx >= params.N) {\n    return;\n  }\n\n  if (params.op == 0u) {\n    output[idx] = a[idx] + b[idx];\n  } else {\n    output[idx] = a[idx] * b[idx];\n  }\n}\n";

export const UPSTREAM_REVISION = "972f3c8";
